<?php
namespace App\Livewire\SuperAdmin;
use App\Models\PlatformAdvertisement;
use Livewire\Component;
use Livewire\WithFileUploads;
class AdvertisementManager extends Component { use WithFileUploads; public bool $showForm=false; public string $title='';public string $message='';public string $audience='all';public int $skipAfterSeconds=5;public string $startsAt='';public string $endsAt='';public $media; public function mount():void{abort_unless(auth()->user()?->hasRole('super-admin'),403);} public function create():void{$this->resetValidation();$this->reset(['title','message','media','startsAt','endsAt']);$this->audience='all';$this->skipAfterSeconds=5;$this->showForm=true;} public function save():void{$this->validate(['title'=>'required|string|max:255','message'=>'nullable|string|max:2000','audience'=>'required|in:all,school-admin,teacher,parent,student,bursar','skipAfterSeconds'=>'required|integer|min:0|max:120','media'=>'required|file|mimes:jpg,jpeg,png,webp,mp4,webm|max:51200','startsAt'=>'nullable|date','endsAt'=>'nullable|date|after_or_equal:startsAt']);$mime=$this->media->getMimeType();$path=$this->media->store('platform-advertisements','public');PlatformAdvertisement::create(['created_by'=>auth()->id(),'title'=>$this->title,'message'=>$this->message?:null,'media_type'=>str_starts_with((string)$mime,'video/')?'video':'image','media_path'=>$path,'audiences'=>[$this->audience],'skip_after_seconds'=>$this->skipAfterSeconds,'starts_at'=>$this->startsAt?:null,'ends_at'=>$this->endsAt?:null,'is_active'=>true]);$this->showForm=false;session()->flash('success','Advertisement published. It will show automatically to the selected audience.');} public function toggle(int $id):void{$ad=PlatformAdvertisement::findOrFail($id);$ad->update(['is_active'=>!$ad->is_active]);} public function render(){return view('livewire.super-admin.advertisement-manager',['ads'=>PlatformAdvertisement::latest()->paginate(15)])->layout('layouts.admin');}}
